WITH base AS (SELECT * FROM inventory WHERE store_id IN (1, 5) OR product_id IN (1, 6, 8)), Summary AS (SELECT YEAR(last_restock) AS last_restock_year, QUARTER(last_restock) AS last_restock_quarter, MIN(last_restock) AS min_last_restock, MIN(last_restock) AS first_last_restock FROM base GROUP BY YEAR(last_restock), QUARTER(last_restock)) SELECT last_restock_year, last_restock_quarter, min_last_restock, first_last_restock FROM Summary ORDER BY first_last_restock DESC, last_restock_quarter DESC;
